 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate a repeated-color strip, encoded either as identical rows or columns.
    seq = None
    for r in range(h):
        vals = [v for v in grid[r] if v]
        if len(vals) >= 2 and len(set(vals)) == len(vals):
            # Verify this is a horizontal palette repeated in adjacent rows.
            repeat = 1
            while r + repeat < h and grid[r + repeat] == grid[r]:
                repeat += 1
            if repeat >= 2:
                seq = vals
                break
    if seq is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h) if grid[r][c]]
            if len(vals) >= 2 and len(set(vals)) == len(vals):
                repeat = 1
                while c + repeat < w and [grid[r][c + repeat] for r in range(h)] == [grid[r][c] for r in range(h)]:
                    repeat += 1
                if repeat >= 2:
                    seq = vals
                    break
    if not seq:
        return [row[:] for row in grid]

    # The silhouette is the connected shape whose color appears in the palette.
    # Remove palette pixels, then select the component matching one palette color.
    palette_colors = set(seq)
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]; seen.add((r, c)); comp = []
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    py, px = p
                    if 0 <= py < h and 0 <= px < w and p not in seen and grid[py][px] == color:
                        seen.add(p); stack.append(p)
            components.append((color, comp))
    choices = [(color, comp) for color, comp in components if color in palette_colors]
    color, comp = max(choices, key=lambda z: len(z[1]))
    minr = min(r for r, c in comp); minc = min(c for r, c in comp)
    mask = [(r-minr, c-minc) for r, c in comp]
    sh = max(r for r, c in mask) + 1
    idx = seq.index(color)
    top = minr - idx * sh
    out = [[0]*w for _ in range(h)]
    for i, col in enumerate(seq):
        y0 = top + i*sh
        for dy, dx in mask:
            y, x = y0+dy, minc+dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = col
    return out
"
